// Recibe el "ping" de venta de Gumroad (form-urlencoded) y lo normaliza.
const it    = $input.first().json;
const body  = it.body  || {};
const query = it.query || {};

// Verificación opcional: añade ?token=TU_SECRETO a la URL del ping en Gumroad.
const expected = it.SHARED_SECRET;
if (expected && expected !== 'REEMPLAZA_TOKEN_SECRETO' && query.token !== expected) {
  return []; // ignora pings sin el token correcto (anti-abuso)
}

const email   = body.email || '';
if (!email) return [];                       // sin email no hay nada que hacer
const name    = body.full_name || 'Cliente';
const product = body.product_name || 'Producto ClinDeck';
const cents   = parseInt(body.price || '0', 10);
const priceUSD = (isFinite(cents) ? cents / 100 : 0).toFixed(2);
const currency = (body.currency || 'usd').toUpperCase();
const saleId   = body.sale_id || '';
const date     = body.sale_timestamp || new Date().toISOString();

return [{ json: {
  email, name, product, priceUSD, currency, saleId, date,
  NOTION_CRM_DB: it.NOTION_CRM_DB,
  DISCOUNT_CODE: it.DISCOUNT_CODE,
  GUMROAD_URL:   it.GUMROAD_URL,
} }];
